Here is the root cause:
Race condition in `tcf_ct_flow_table_get()` where `rhashtable_lookup_fast()` internally releases the RCU read lock before the subsequent `refcount_inc_not_zero()` call. This allows a concurrent `tcf_ct_flow_table_put()` to free the `ct_ft` object via RCU work between the lookup and the reference increment, leading to a use-after-free vulnerability.

Here is the patch:

 static int tcf_ct_flow_table_get(struct net *net, struct tcf_ct_params *params)
 {
 	struct zones_ht_key key = { .net = net, .zone = params->zone };
 	struct tcf_ct_flow_table *ct_ft;
 	int err = -ENOMEM;

 	mutex_lock(&zones_mutex);
-	ct_ft = rhashtable_lookup_fast(&zones_ht, &key, zones_params);
-	if (ct_ft && refcount_inc_not_zero(&ct_ft->ref))
+	rcu_read_lock();
+	ct_ft = rhashtable_lookup(&zones_ht, &key, zones_params);
+	if (ct_ft && refcount_inc_not_zero(&ct_ft->ref)) {
+		rcu_read_unlock();
 		goto out_unlock;
+	}
+	rcu_read_unlock();

 	ct_ft = kzalloc_obj(*ct_ft);
 	if (!ct_ft)
 		goto err_alloc;
 	refcount_set(&ct_ft->ref, 1);

 	ct_ft->key = key;
 	err = rhashtable_insert_fast(&zones_ht, &ct_ft->node, zones_params);
 	if (err)
 		goto err_insert;

 	ct_ft->nf_ft.type = &flowtable_ct;
 	ct_ft->nf_ft.flags |= NF_FLOWTABLE_HW_OFFLOAD |
 			      NF_FLOWTABLE_COUNTER;
 	err = nf_flow_table_init(&ct_ft->nf_ft);
 	if (err)
 		goto err_init;
 	write_pnet(&ct_ft->nf_ft.net, net);

 	__module_get(THIS_MODULE);
 out_unlock:
 	params->ct_ft = ct_ft;
 	params->nf_ft = &ct_ft->nf_ft;
 	mutex_unlock(&zones_mutex);

 	return 0;

 err_init:
 	rhashtable_remove_fast(&zones_ht, &ct_ft->node, zones_params);
 err_insert:
 	kfree(ct_ft);
 err_alloc:
 	mutex_unlock(&zones_mutex);
 	return err;
 }



